#pragma once
// Zeus lightning-dial geometry. Pure C++ (no JUCE) so it is unit tested in Tests/test_zeus_rig.cpp.
//
// One intensity value (derived from the "retune" parameter via RetuneDialMapping) drives:
//   * which of the nine Zeus poses is shown,
//   * the point on the 270-degree meter where the gold fill ends,
//   * the bolt transform, which maps the bolt's grip to the pose's fist and its tip EXACTLY onto
//     that meter point. The bolt is therefore the physical knob pointer; there is no second one.
// All coordinates are Zeus Rig V2 canvas pixels (see ZeusRigData.h, generated by
// tools/build_zeus_assets.py). The editor maps canvas -> screen with one uniform scale + offset.
#include "RetuneDialMapping.h"
#include "ZeusRigData.h"
#include <algorithm>
#include <cmath>
#include <cstddef>

namespace evolutionvox::ui::zeus {

constexpr int numPoses = static_cast<int>(poses.size());

// Nearest-pose selection with a small hysteresis so automation hovering on a boundary between
// two poses does not make Zeus flicker. previous < 0 means "no previous pose".
inline int poseForIntensity(float intensity, int previous = -1, float hysteresis = 1.0f) noexcept {
    intensity = RetuneDialMapping::clampIntensity(intensity);
    int best = 0;
    for (int i = 1; i < numPoses; ++i)
        if (std::abs(poses[static_cast<size_t>(i)].intensity - intensity)
            < std::abs(poses[static_cast<size_t>(best)].intensity - intensity))
            best = i;
    if (previous >= 0 && previous < numPoses && previous != best && std::abs(previous - best) == 1) {
        // Stay on the previous pose until the value is clearly past the midpoint between them.
        const float midpoint = 0.5f * (poses[static_cast<size_t>(previous)].intensity
                                       + poses[static_cast<size_t>(best)].intensity);
        if (std::abs(intensity - midpoint) < hysteresis)
            return previous;
    }
    return best;
}

// Meter point (canvas) for an intensity, using the single source of truth for the angle.
inline Point meterPoint(float intensity) noexcept {
    const float radians = RetuneDialMapping::pointerDegrees(intensity) * RetuneDialMapping::pi / 180.0f;
    return { dialCentreX + dialRadius * std::cos(radians), dialCentreY + dialRadius * std::sin(radians) };
}

// Affine transform taking bolt-image pixels to canvas pixels:
//   canvas = [m00 m01; m10 m11] * image + [dx; dy]
struct BoltTransform {
    float m00 = 1, m01 = 0, dx = 0;
    float m10 = 0, m11 = 1, dy = 0;
    float stretch = 1;   // bolt length ratio vs. the source art (diagnostic)
    Point tip {};        // where the tip lands (canvas) == meterPoint(intensity)

    Point apply(Point p) const noexcept { return { m00 * p.x + m01 * p.y + dx, m10 * p.x + m11 * p.y + dy }; }
};

inline BoltTransform boltTransform(int poseIndex, float intensity) noexcept {
    const auto& pose = poses[static_cast<size_t>(std::clamp(poseIndex, 0, numPoses - 1))];
    const Point tip = meterPoint(intensity);
    const float srcX = pose.boltTip.x - pose.boltAnchor.x, srcY = pose.boltTip.y - pose.boltAnchor.y;
    const float dstX = tip.x - pose.fist.x, dstY = tip.y - pose.fist.y;
    const float srcLen = std::max(1.0f, std::hypot(srcX, srcY));
    const float dstLen = std::max(1.0f, std::hypot(dstX, dstY));
    const float stretch = dstLen / srcLen;
    // Scale uniformly within limits (a longer bolt also gets a little thicker); the rest of the
    // length change happens along the bolt's own axis only, so it never balloons or collapses.
    const float across = std::clamp(stretch, boltUniformScaleMin, boltUniformScaleMax);
    const float along = stretch;
    const float c0 = srcX / srcLen, s0 = srcY / srcLen;   // source direction
    const float c1 = dstX / dstLen, s1 = dstY / dstLen;   // target direction
    // M = R(target) * diag(along, across) * R(-source)
    BoltTransform t;
    t.m00 = c1 * along * c0 + s1 * across * s0;
    t.m01 = c1 * along * s0 - s1 * across * c0;
    t.m10 = s1 * along * c0 - c1 * across * s0;
    t.m11 = s1 * along * s0 + c1 * across * c0;
    t.dx = pose.fist.x - (t.m00 * pose.boltAnchor.x + t.m01 * pose.boltAnchor.y);
    t.dy = pose.fist.y - (t.m10 * pose.boltAnchor.x + t.m11 * pose.boltAnchor.y);
    t.stretch = stretch;
    t.tip = tip;
    return t;
}

// Canvas-space bounds of everything the dial can draw (arc + glow + every pose), so the editor
// can size the scene without clipping. The arc has a 90-degree gap at the bottom, so its lowest
// points are the two 45-degree ends, not centre + radius.
struct Bounds { float x0, y0, x1, y1; };
inline Bounds sceneBounds(float arcMargin) noexcept {
    Bounds b { dialCentreX - dialRadius - arcMargin, dialCentreY - dialRadius - arcMargin,
               dialCentreX + dialRadius + arcMargin, meterPoint(0.0f).y + arcMargin };
    for (const auto& p : poses)
        for (const auto& r : { p.base, p.arm }) {
            b.x0 = std::min(b.x0, static_cast<float>(r.x));
            b.y0 = std::min(b.y0, static_cast<float>(r.y));
            b.x1 = std::max(b.x1, static_cast<float>(r.x + r.w));
            b.y1 = std::max(b.y1, static_cast<float>(r.y + r.h));
        }
    return b;
}

} // namespace evolutionvox::ui::zeus
